3Cmn\u003E2\u003C/mn\u003E\n    \u003C/mrow\u003E\n  \u003C/msup\u003E\n  \u003Cmo\u003E=\u003C/mo\u003E\n  \u003Cmn\u003E2\u003C/mn\u003E\n  \u003Cmsup\u003E\n    \u003Cmi\u003Ex\u003C/mi\u003E\n    \u003Cmrow data-mjx-texclass=\"ORD\"\u003E\n      \u003Cmn\u003E2\u003C/mn\u003E\n    \u003C/mrow\u003E\n  \u003C/msup\u003E\n  \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n  \u003Cmn\u003E1\u003C/mn\u003E\n  \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n  \u003Cmi\u003Eq\u003C/mi\u003E\n  \u003Cmtext mathcolor=\"red\"\u003E\\p\u003C/mtext\u003E\n  \u003Cmo\u003E=\u003C/mo\u003E\n  \u003Cmfrac\u003E\n    \u003Cmrow\u003E\n      \u003Cmo stretchy=\"false\"\u003E(\u003C/mo\u003E\n      \u003Cmn\u003E2\u003C/mn\u003E\n      \u003Cmsup\u003E\n        \u003Cmi\u003Ex\u003C/mi\u003E\n        \u003Cmrow data-mjx-texclass=\"ORD\"\u003E\n          \u003Cmn\u003E2\u003C/mn\u003E\n        \u003C/mrow\u003E\n      \u003C/msup\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmi\u003Eq\u003C/mi\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmn\u003E1\u003C/mn\u003E\n      \u003Cmo stretchy=\"false\"\u003E)\u003C/mo\u003E\n    \u003C/mrow\u003E\n    \u003Cmsup\u003E\n      \u003Cmi\u003Ex\u003C/mi\u003E\n      \u003Cmrow data-mjx-texclass=\"ORD\"\u003E\n        \u003Cmn\u003E2\u003C/mn\u003E\n      \u003C/mrow\u003E\n    \u003C/msup\u003E\n  \u003C/mfrac\u003E\n  \u003Cmtext mathcolor=\"red\"\u003E\\At\u003C/mtext\u003E\n  \u003Cmspace width=\"1mm\"\u003E\u003C/mspace\u003E\n  \u003Cmi\u003Ex\u003C/mi\u003E\n  \u003Cmo\u003E=\u003C/mo\u003E\n  \u003Cmn\u003E2\u003C/mn\u003E\n  \u003Cmtext mathcolor=\"red\"\u003E\\p\u003C/mtext\u003E\n  \u003Cmo\u003E=\u003C/mo\u003E\n  \u003Cmfrac\u003E\n    \u003Cmrow\u003E\n      \u003Cmn\u003E2\u003C/mn\u003E\n      \u003Cmo stretchy=\"false\"\u003E(\u003C/mo\u003E\n      \u003Cmsup\u003E\n        \u003Cmn\u003E2\u003C/mn\u003E\n        \u003Cmrow data-mjx-texclass=\"ORD\"\u003E\n          \u003Cmn\u003E2\u003C/mn\u003E\n        \u003C/mrow\u003E\n      \u003C/msup\u003E\n      \u003Cmo stretchy=\"false\"\u003E)\u003C/mo\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmn\u003E1\u003C/mn\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmi\u003Eq\u003C/mi\u003E\n      \u003Cmo stretchy=\"false\"\u003E)\u003C/mo\u003E\n    \u003C/mrow\u003E\n    \u003Cmsup\u003E\n      \u003Cmn\u003E2\u003C/mn\u003E\n      \u003Cmrow data-mjx-texclass=\"ORD\"\u003E\n        \u003Cmn\u003E2\u003C/mn\u003E\n      \u003C/mrow\u003E\n    \u003C/msup\u003E\n  \u003C/mfrac\u003E\n  \u003Cmtext mathcolor=\"red\"\u003E\\p\u003C/mtext\u003E\n  \u003Cmo\u003E=\u003C/mo\u003E\n  \u003Cmfrac\u003E\n    \u003Cmrow\u003E\n      \u003Cmo stretchy=\"false\"\u003E(\u003C/mo\u003E\n      \u003Cmn\u003E8\u003C/mn\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmn\u003E1\u003C/mn\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmi\u003Eq\u003C/mi\u003E\n      \u003Cmo stretchy=\"false\"\u003E)\u003C/mo\u003E\n    \u003C/mrow\u003E\n    \u003Cmn\u003E4\u003C/mn\u003E\n  \u003C/mfrac\u003E\n  \u003Cmtext mathcolor=\"red\"\u003E\\=\u003C/mtext\u003E\n  \u003Cmfrac\u003E\n    \u003Cmrow\u003E\n      \u003Cmn\u003E7\u003C/mn\u003E\n      \u003Cmo\u003E&#x2212;\u003C/mo\u003E\n      \u003Cmi\u003Eq\u003C/mi\u003E\n    \u003C/mrow\u003E\n    \u003Cmn\u003E4\u003C/mn\u003E\n  \u003C/mfrac\u003E\n\u003C/math\u003E                                             ",
        "image": "",
